class Solution { public:
 string shortestBeautifulSubstring(string s,int k){
  string best="";int n=s.size();for(int i=0;i<n;++i){if(s[i]!='1')continue;int ones=0;
   for(int j=i;j<n;++j){ones+=s[j]=='1';if(ones>k)break;
    if(ones==k){string cur=s.substr(i,j-i+1);if(best.empty()||cur.size()<best.size()||(cur.size()==best.size()&&cur<best))best=cur;break;}}
  }return best;
 }
};
